import React from "react";
import { Link } from "react-router-dom";
import { FaCartPlus } from "react-icons/fa";

const API_URL = import.meta.env.VITE_API_BASE_URL || "";

export default function ProductCard({ product = {}, onAddToCart }) {
  // Safe values with fallback defaults
  const id = product.id || product._id || "unknown";
  const name = product.name || "Unnamed Product";
  const description = product.description || "No description";
  const price = product.price != null ? product.price : "N/A";

  // Safe image URL handling
  const imageUrl =
    product.imageUrl && product.imageUrl.startsWith("http")
      ? product.imageUrl
      : product.imageUrl
      ? `${API_URL}${product.imageUrl.startsWith("/") ? "" : "/images/"}${
          product.imageUrl
        }`
      : `${API_URL}/images/placeholder.webp`;

  return (
    <div className="bg-white rounded-lg shadow-md hover:shadow-xl transition p-4 flex flex-col group">
      {/* Product Image */}
      <Link to={`/product/${id}`} className="flex-1">
        <div className="w-full h-48 flex items-center justify-center overflow-hidden rounded-t-lg bg-gray-50">
          <img
            src={imageUrl}
            alt={name}
            className="max-h-full object-contain transition-transform duration-300 group-hover:scale-105"
            loading="lazy"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src = `${API_URL}/images/placeholder.webp`;
            }}
          />
        </div>
        <div className="p-4">
          <h3 className="text-lg font-semibold truncate">{name}</h3>
          <p className="text-sm text-gray-500 mt-1 truncate">{description}</p>
          <p className="text-blue-600 font-bold mt-2">Rs {price}</p>
        </div>
      </Link>

      {/* Add to Cart Button */}
      <button
        onClick={() => onAddToCart?.(product)}
        className="mt-2 bg-purple-700 text-white py-2 rounded hover:bg-purple-800 transition flex items-center justify-center gap-2"
      >
        <FaCartPlus /> Add to Cart
      </button>
    </div>
  );
}
