// src/pages/ProductList.jsx
import React, { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import axios from "axios";
import { useSearchParams } from "react-router-dom";
import ProductCard from "../components/ProductCard";
import SearchBar from "../components/SearchBar";

// ✅ Use .env backend URL
const API_URL = import.meta.env.VITE_API_BASE_URL;

export default function ProductList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [categories, setCategories] = useState([]);

  const search = searchParams.get("search") || "";
  const category = searchParams.get("category") || "";
  const sort = searchParams.get("sort") || "";
  const page = Number(searchParams.get("page") || 1);

  // ✅ React Query to fetch products
  const { data, isLoading, error } = useQuery({
    queryKey: ["products", { search, category, sort, page }],
    queryFn: async () => {
      const res = await axios.get(`${API_URL}/api/products`, {
        params: { search, category, sort, page },
      });

      // Ensure response has consistent shape
      if (Array.isArray(res.data)) {
        return { products: res.data, totalPages: 1 };
      }

      return {
        products: Array.isArray(res.data?.products)
          ? res.data.products
          : [],
        totalPages: Number(res.data?.totalPages) > 0 ? res.data.totalPages : 1,
      };
    },
    keepPreviousData: true,
    refetchOnWindowFocus: false,
    retry: 1,
  });

  const products = Array.isArray(data?.products) ? data.products : [];
  const totalPages = Number(data?.totalPages) > 0 ? Number(data.totalPages) : 1;

  // ✅ Load categories from backend
  useEffect(() => {
    axios
      .get(`${API_URL}/api/categories`)
      .then((res) => {
        if (Array.isArray(res.data)) {
          setCategories(res.data);
        } else if (Array.isArray(res.data?.categories)) {
          setCategories(res.data.categories);
        } else {
          setCategories([]);
        }
      })
      .catch((err) => {
        console.error("Error loading categories", err);
        setCategories([]);
      });
  }, []);

  const handleFilterChange = (key, value) => {
    const newParams = new URLSearchParams(searchParams);
    if (value) newParams.set(key, value);
    else newParams.delete(key);
    newParams.set("page", "1");
    setSearchParams(newParams);
  };

  if (isLoading)
    return (
      <div className="flex justify-center items-center h-64 text-gray-500">
        Loading products...
      </div>
    );

  if (error)
    return (
      <div className="flex justify-center items-center h-64 text-red-600">
        Failed to load products.
      </div>
    );

  return (
    <div className="max-w-7xl mx-auto p-6">
      <h2 className="text-3xl font-bold mb-6 text-purple-700">All Products</h2>

      {/* Search Bar */}
      <div className="mb-6">
        <SearchBar />
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-4 mb-6">
        {/* Category Filter */}
        <select
          value={category}
          onChange={(e) => handleFilterChange("category", e.target.value)}
          className="border px-3 py-2 rounded shadow-sm focus:ring-2 focus:ring-purple-400"
        >
          <option value="">All Categories</option>
          {Array.isArray(categories) && categories.length > 0 ? (
            categories.map((cat) => (
              <option key={cat._id || cat.id} value={cat._id || cat.id}>
                {cat.name}
              </option>
            ))
          ) : (
            <option disabled>No categories</option>
          )}
        </select>

        {/* Sort Filter */}
        <select
          value={sort}
          onChange={(e) => handleFilterChange("sort", e.target.value)}
          className="border px-3 py-2 rounded shadow-sm focus:ring-2 focus:ring-purple-400"
        >
          <option value="">Sort By</option>
          <option value="price-asc">Price Low to High</option>
          <option value="price-desc">Price High to Low</option>
          <option value="name-asc">Name A-Z</option>
          <option value="name-desc">Name Z-A</option>
        </select>
      </div>

      {/* Product Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
        {products.length > 0 ? (
          products.map((product) => (
            <ProductCard key={product._id || product.id} product={product} />
          ))
        ) : (
          <div className="col-span-full text-gray-500 text-center">
            No products found.
          </div>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex justify-center mt-8 gap-2 flex-wrap">
          {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
            <button
              key={p}
              onClick={() => handleFilterChange("page", p)}
              className={`px-4 py-2 border rounded ${
                p === page
                  ? "bg-purple-700 text-white shadow-md"
                  : "bg-white text-gray-700 hover:bg-purple-100 transition"
              }`}
            >
              {p}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
